from collections import Counter

class Solution:
    def equalPairs(self, grid: list[list[int]]) -> int:
        n = len(grid)
        row_counts = Counter(tuple(row) for row in grid)
        ans = 0
        for c in range(n):
            col = tuple(grid[r][c] for r in range(n))
            ans += row_counts[col]
        return ans

class Solution {
public:
    int equalPairs(std::vector<std::vector<int>>& grid) {
        int n = grid.size();
        std::map<std::vector<int>, int> row_counts;
        for (const auto& row : grid) row_counts[row]++;
        int ans = 0;
        for (int c = 0; c < n; ++c) {
            std::vector<int> col(n);
            for (int r = 0; r < n; ++r) col[r] = grid[r][c];
            if (row_counts.count(col)) ans += row_counts[col];
        }
        return ans;
    }
};

class Solution {
    public int equalPairs(int[][] grid) {
        int n = grid.length;
        java.util.Map<String, Integer> rowCounts = new java.util.HashMap<>();
        for (int[] row : grid) {
            StringBuilder sb = new StringBuilder();
            for (int x : row) sb.append(x).append(",");
            String key = sb.toString();
            rowCounts.put(key, rowCounts.getOrDefault(key, 0) + 1);
        }
        int ans = 0;
        for (int c = 0; c < n; ++c) {
            StringBuilder sb = new StringBuilder();
            for (int r = 0; r < n; ++r) sb.append(grid[r][c]).append(",");
            String key = sb.toString();
            ans += rowCounts.getOrDefault(key, 0);
        }
        return ans;
    }
}

var equalPairs = function(grid) {
    const n = grid.length;
    const map = new Map();
    for (const row of grid) {
        const key = row.join(',');
        map.set(key, (map.get(key) || 0) + 1);
    }
    let ans = 0;
    for (let c = 0; c < n; ++c) {
        const col = [];
        for (let r = 0; r < n; ++r) col.push(grid[r][c]);
        const key = col.join(',');
        ans += map.get(key) || 0;
    }
    return ans;
};
